do $$ declare n int; begin
  select count(*) into n from deterministic_replies d join tenants t on t.id = d.tenant_id
   where t.slug = 'dalatech' and d.intent in ('annual_prepay','vat_receipt','contract_minimum','nova_about');
  if n <> 4 then raise exception 'expected 4 new rows, found %', n; end if;
  if exists (select 1 from deterministic_replies d join tenants t on t.id = d.tenant_id
              where t.slug = 'dalatech' and d.enabled and d.body like '%−%') then raise exception 'a row still writes a minus sign'; end if;
  if exists (select 1 from faqs f join tenants t on t.id = f.tenant_id
              where t.slug = 'dalatech' and f.answer like '%−%') then raise exception 'a FAQ still writes a minus sign'; end if;
  select count(*) into n from knowledge_documents k join tenants t on t.id = k.tenant_id
   where t.slug = 'dalatech' and k.body like '%2 сар үнэгүй%' and k.body like '%30 хоногийн өмнө%' and k.body like '%И-баримт%';
  if n <> 1 then raise exception 'Үнийн нөхцөл does not carry all three approved lines'; end if;
  select count(*) into n from knowledge_documents k join tenants t on t.id = k.tenant_id
   where t.slug = 'dalatech' and k.body like '%ТИЙМ/ҮГҮЙ хариуг хүлээн авдаг AI ажилтан%';
  if n <> 1 then raise exception 'Нова''s document does not carry the approved line'; end if;
  if (select count(*) from faqs f join tenants t on t.id = f.tenant_id where t.slug = 'dalatech' and f.answer in (normalize('Тийм ээ, 2 AI ажилтан авбал сарын төлбөрт 10%-ийн хөнгөлөлт эдэлнэ. 3 ажилтанд 15%, 4-өөс дээш бол 20%.', NFC), normalize('Жилийн төлбөрөө урьдчилан төлбөл 2 сар үнэгүй — 10 сарын төлбөрөөр 12 сар ажиллуулна. Энэ хөнгөлөлтийг бусад хөнгөлөлттэй хамт тооцохгүй.', NFC), normalize('Гэрээний доод хугацаа 3 сар байдаг. Үүний дараа сар бүр үргэлжлүүлэх, эсвэл 30 хоногийн өмнө мэдэгдэж цуцлах боломжтой.', NFC), normalize('Уучлаарай, манайх одоогоор НӨАТ-ын баримт (И-баримт) өгөх боломжгүй байгаа. Үнэд НӨАТ нэмж тооцогдохгүй тул таны төлөх дүн яг үнийн дүнтэй адил байна.', NFC))) <> 4 then
    raise exception 'not all four FAQ answers were replaced';
  end if;
end $$;
commit;
